        # Horizontal aisle
        if x1 != x2:
            r_min, r_max = sorted((x1, x2))
            for r in range(r_min, r_max):
                row_separators[r].add(idx)
        # Vertical aisle
        if y1 != y2:
            c_min, c_max = sorted((y1, y2))
            for c in range(c_min, c_max):
                col_separators[c].add(idx)

    # Helper to compute union size for given sets
    def union_size(row_set, col_set):
        total = set()
