def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to a maximum of 10 steps. Returns the minimum number of steps
    required to transform A into B, or "NO ANSWER!" if impossible within 10 steps.
    """
    from collections import deque
    from typing import Union

    # Basic validation
    if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
        raise TypeError("A and B must be strings, rules must be a list of tuples.")
    for rule in rules:
        if not (isinstance(rule, tuple) and len(rule) == 2 and isinstance(rule[0], str) and isinstance(rule[1], str)):
            raise ValueError("Each rule must be a tuple of two strings (source, target).")

    # If already equal
    if A == B:
        return 0

    max_depth = 10
    visited = {A}
    queue = deque([(A, 0)])

    while queue:
        current, depth = queue.popleft()
        if depth >= max_depth:
            continue
        next_depth = depth + 1
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return next_depth
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, next_depth))
                start = idx + 1  # allow overlapping matches
    return "NO ANSWER!"

