            subject = speaker.upper()
            if words[1].lower() != 'am':
                return None
            if words[2].lower() == 'guilty':
                guilty = True
            elif words[2].lower() == 'not' and len(words) >= 4 and words[3].lower() == 'guilty':
                guilty = False
            else:
                return None
        else:
            subject = words[0].upper()
            if words[1].lower() != 'is':
                return None
            if words[2].lower() == 'guilty':
                guilty = True
            elif words[2].lower() == 'not' and len(words) >= 4 and words[3].lower() == 'guilty':
                guilty = False
            else:
